import React, { useState, useEffect } from 'react';
import { useParams, useLocation } from 'react-router-dom';
import { collection, addDoc, query, where, onSnapshot, serverTimestamp, doc, getDoc, updateDoc, and, or } from 'firebase/firestore';
import { db, auth } from '../../firebase';
import { onAuthStateChanged } from 'firebase/auth';

const ChatPage = () => {
  const { postId } = useParams();
  const location = useLocation();
  const listing = location.state?.listing;
  const [user, setUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [recipientId, setRecipientId] = useState(null);
  const [recipientEmail, setRecipientEmail] = useState('');

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    const fetchPostDetails = async () => {
      const postDoc = await getDoc(doc(db, 'posts', postId));
      if (postDoc.exists()) {
        const postData = postDoc.data();
        setRecipientId(postData.userId);
        try {
          const recipientDoc = await getDoc(doc(db, 'users', postData.userId));
          if (recipientDoc.exists()) {
            setRecipientEmail(recipientDoc.data().email);
          }
        } catch (error) {
          console.error("Error fetching recipient details: ", error);
        }
      }
    };
    fetchPostDetails();
  }, [postId]);

  useEffect(() => {
    if (user && recipientId) {
      const q = query(
        collection(db, 'chats'),
        and(
          where('postId', '==', postId),
          or(
            and(where('userId', '==', user.uid), where('recipientId', '==', recipientId)),
            and(where('userId', '==', recipientId), where('recipientId', '==', user.uid))
          )
        )
      );
      const unsubscribe = onSnapshot(q, (querySnapshot) => {
        const msgs = querySnapshot.docs.map(doc => doc.data());
        setMessages(msgs);
      });
      return () => unsubscribe();
    }
  }, [postId, user, recipientId]);

  const handleSendMessage = async (e) => {
    e.preventDefault();
    if (!user) {
      alert('You must be logged in to send a message.');
      return;
    }
    if (newMessage.trim() === '') return;

    const messageData = {
      postId,
      userId: user.uid,
      recipientId,
      message: newMessage,
      timestamp: serverTimestamp(),
    };

    // Clear the text input immediately
    setNewMessage('');

    try {
      await addDoc(collection(db, 'chats'), messageData);

      // Check if the recipient document exists before updating
      const recipientDocRef = doc(db, 'users', recipientId);
      const recipientDoc = await getDoc(recipientDocRef);
      if (recipientDoc.exists()) {
        await updateDoc(recipientDocRef, {
          hasNewMessage: true,
        });
      } else {
        console.warn("Recipient document does not exist.");
      }

    } catch (error) {
      console.error("Error sending message: ", error);
      alert("Error sending message: " + error.message);
    }
  };

  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-2xl font-semibold mb-4">Chat</h1>
      {listing ? (
        <div className="bg-gray-100 p-4 rounded-lg mb-4">
          <h2 className="text-xl font-semibold">{listing.title}</h2>
          <p className="text-gray-600">{listing.description}</p>
        </div>
      ) : (
        <p className="text-gray-600">No listing details available</p>
      )}
      <div className="bg-white p-4 rounded-lg shadow-md mb-4">
        {messages.length > 0 ? (
          messages.slice().reverse().map((msg, index) => (
            <div
              key={index}
              className={`mb-2 p-2 rounded-lg ${msg.userId === user.uid ? 'bg-blue-100 text-right' : 'bg-gray-100 text-left'}`}
            >
              <p className="text-sm">{msg.message}</p>
            </div>
          ))
        ) : (
          <p className="text-gray-600">No messages available</p>
        )}
      </div>
      <form onSubmit={handleSendMessage} className="flex">
        <input
          type="text"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          placeholder="Type your message..."
          className="flex-grow p-2 border rounded-l-md"
        />
        <button type="submit" className="bg-red-500 text-white px-4 py-2 rounded-r-md">Send</button>
      </form>
    </div>
  );
};

export default ChatPage;
